<template>
  <section class="local-builder">
    <div class="local-heading"><div><span class="kicker">PLACE · COMMUNITY · CULTURE</span><h2>区域与社区人群模型</h2></div><span :class="['binding',dirty?'stale':'ready']">{{ !template ? '尚未生成本地画像' : dirty ? '配置已变化 · 需要重新生成' : '画像已绑定当前区域' }}</span></div>
    <p>国家与城市确定范围，场所决定来访任务，社区资料用于校正文化、生活方式与活动习惯。资料不足时保留假设，不把国家特征套到每个人身上。</p>
    <details :open="!template || dirty"><summary>设置国家、社区、场所与资料</summary>
      <div class="location-fields"><label>国家 / 地区<input v-model="value.country" :disabled="disabled" placeholder="例如 United States of America" maxlength="200"></label><label>城市 / 地区<input v-model="value.city" :disabled="disabled" placeholder="城市或明确的行政区域" maxlength="200"></label><label>社区 / 服务范围<input v-model="value.community" :disabled="disabled" placeholder="街区、商圈、社区或交通服务范围" maxlength="200"></label><label>场所类型<select aria-label="场所类型" v-model="value.venue_type" :disabled="disabled"><option value="">请选择</option><option v-for="v in venues" :key="v.id" :value="v.id">{{ v.name }}</option></select></label><label>具体地点 / 场所名称<input v-model="value.venue_name" :disabled="disabled" placeholder="可选；未核实名称请标注为情景" maxlength="200"></label><label>语言环境与依据<input v-model="value.languages" :disabled="disabled" placeholder="有资料时填写；否则留空，不按国家猜测" maxlength="500"></label></div>
      <div class="notes-grid"><label>区域文化线索与依据<textarea v-model="value.cultural_notes" :disabled="disabled" rows="3" maxlength="4000" placeholder="公共空间、文化活动、生活习惯；请区分资料与假设" /></label><label>社区生活与社会联系<textarea v-model="value.community_notes" :disabled="disabled" rows="3" maxlength="4000" placeholder="居民、工作者、来访者关系，社区服务、家庭任务与资料缺口" /></label></div>
      <div class="import-row"><button :disabled="disabled || loading" @click="loadInventory(false)">读取测试库存地点</button><button v-if="projectId" :disabled="disabled || loading" @click="loadInventory(true)">读取当前库存与资料</button><span>提取原始线索，不自动确认社区边界。</span></div>
      <div v-if="inventory" class="inventory-hints"><p>{{ inventory.warning }}</p><select aria-label="库存地点线索" v-model="inventorySelection" :disabled="disabled"><option value="">选择一条库存记录</option><option v-for="c in inventory.candidates" :value="c.screen_id" :key="c.screen_id">{{ c.city }} · {{ c.address }} · {{ c.screen_id.slice(0,8) }}</option></select><div v-if="candidate"><p>国家：{{ candidate.country }} · 城市：{{ candidate.city }}<br>地址：{{ candidate.address }}<br>场所：{{ candidate.venue }} · POI：{{ candidate.poi }}</p><button :disabled="disabled" @click="applyCandidate">填入地点线索，手动核对社区</button></div></div>
      <div class="source-heading"><h3>区域资料与消费者调研</h3><button :disabled="disabled || value.sources.length>=12" @click="addSource">＋ 添加资料</button></div>
      <p class="hint">粘贴资料摘录并填写适用国家、城市；社区留空表示城市级资料。来源链接只作引用，不自动抓取。其他地区或未标范围的资料会排除。</p>
      <details v-for="(s,i) in value.sources" :key="s.id" class="source-item" open><summary>{{ s.title || `资料 ${i+1}` }} <small>{{ s.city || '范围未指定' }}</small></summary><div class="location-fields"><label>资料标题<input v-model="s.title" :disabled="disabled" maxlength="200"></label><label>适用国家<input v-model="s.country" :disabled="disabled" maxlength="200"></label><label>适用城市<input v-model="s.city" :disabled="disabled" maxlength="200"></label><label>适用社区（可选）<input v-model="s.community" :disabled="disabled" maxlength="200"></label><label>资料类型<select v-model="s.kind" :disabled="disabled" aria-label="资料类型"><option value="document">区域 / 社区资料</option><option value="survey">消费者调研</option><option value="assumption">情景假设</option><option value="inventory">库存原始字段</option></select></label><label>来源链接<input v-model="s.url" :disabled="disabled" maxlength="1500" placeholder="https://…（可选）"></label></div><label>资料摘录<textarea v-model="s.text" :disabled="disabled" rows="4" maxlength="8000" /></label><button :disabled="disabled" @click="value.sources.splice(i,1)">移除此资料</button></details>
    </details>
    <div class="generation-actions"><label>细分群体数量<input :value="groupCount" @input="$emit('update:groupCount',Number($event.target.value))" type="number" min="4" max="20" :disabled="disabled"></label><button class="generate" :disabled="disabled" @click="$emit('generate')">{{ generating?'正在研究地区与社区…':'按地区与场所生成人群' }}</button><span>调用一次 LLM 生成模板；之后仍由代表性 Agent 逐小时决策。</span></div>
    <p v-if="error" role="alert" class="local-error">{{ error }}</p>
    <div v-if="template" class="template-evidence"><h3>模板依据 <span>{{ template.grounding==='scenario_only'?'场景假设 · 缺少适用来源':'资料辅助推演 · 非人口统计' }}</span></h3><p>{{ template.summary }}</p><ul><li v-for="(u,i) in template.uncertainties" :key="i">{{ u }}</li></ul><p v-for="s in template.ignored_sources" :key="s.id" class="ignored">已排除 {{ s.title }}：{{ s.reason }}</p><div class="source-links"><span v-for="s in value.sources.filter(s=>template.used_source_ids?.includes(s.id))" :key="s.id">{{ s.id }} · <a v-if="s.url" :href="s.url" target="_blank" rel="noopener noreferrer">{{ s.title }}</a><span v-else>{{ s.title }}</span></span></div></div>
  </section>
</template>
<script setup>
import {ref,computed} from 'vue'
import api from '../api'
const value=defineModel({required:true})
const props=defineProps({template:Object,dirty:Boolean,disabled:Boolean,generating:Boolean,venues:Array,groupCount:Number,projectId:String})
defineEmits(['generate','update:groupCount'])
const inventory=ref(null),inventorySelection=ref(''),loading=ref(false),error=ref('')
const candidate=computed(()=>inventory.value?.candidates.find(c=>c.screen_id===inventorySelection.value))
async function loadInventory(useProject){loading.value=true;error.value='';try{const r=await api.post('/api/world/location-inventory',useProject?{project_id:props.projectId}:{});inventory.value=r.data;inventorySelection.value='';if(useProject){for(const d of r.data.documents){if(value.value.sources.length<12&&!value.value.sources.some(s=>s.id===d.id))value.value.sources.push(d)}}}catch(e){error.value=e.message}finally{loading.value=false}}
function applyCandidate(){const c=candidate.value;value.value.country=c.country;value.value.city=c.city;value.value.community='';value.value.venue_name=c.address;const v=c.venue.toLowerCase();value.value.venue_type=v.includes('airport')?'airport':v.includes('supermarket')?'supermarket':v.includes('mall')?'mall':/station|transit|train/.test(v)?'station':/outdoor|street|billboard/.test(v)?'street':'custom';const id='inventory-'+c.screen_id;value.value.sources=value.value.sources.filter(s=>s.id!==id);if(value.value.sources.length<12)value.value.sources.push({id,title:`${inventory.value.filename} · 库存地点线索`,text:JSON.stringify(c,null,2),country:c.country,city:c.city,community:'',url:'',kind:'inventory'})}
function addSource(){value.value.sources.push({id:`source-${Date.now()}`,title:'',text:'',country:value.value.country,city:value.value.city,community:'',url:'',kind:'document'})}
</script>
<style scoped>
.local-builder{border:1px solid #dce2e5;border-radius:10px;background:#ffffff;padding:20px 22px;margin-bottom:20px;color:#191d21}.local-heading{display:flex;align-items:center;justify-content:space-between;gap:15px}.kicker{font-size:9px;letter-spacing:2px;color:#525b65}h2{font-size:18px;margin:7px 0}h3{font-size:13px;font-weight:500}.binding{font-size:11px;padding:6px 10px;border-radius:20px;border:1px solid #dce2e5;white-space:nowrap}.ready{color:#191d21}.stale{color:#191d21;border-color:#dce2e5}.local-builder p{font-size:12px;line-height:1.8;color:#525b65;margin:12px 0}.local-builder summary{cursor:pointer;color:#191d21;font-size:12px;padding:10px 0}.location-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:10px}.notes-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.local-builder label{display:block;font-size:12px;color:#191d21;margin-bottom:10px;min-width:0}.local-builder input,.local-builder textarea,.local-builder select{width:100%;padding:9px;border:1px solid #dce2e5;border-radius:5px;background:#ffffff;color:#191d21;font:inherit;display:block;margin-top:7px;min-width:0}.local-builder textarea{resize:vertical}.local-builder input:disabled,.local-builder textarea:disabled,.local-builder select:disabled{opacity:.55}.local-builder button{border:1px solid #dce2e5;background:#f1f5f4;color:#191d21;border-radius:5px;padding:8px 12px;font-size:12px;cursor:pointer}.local-builder button:disabled{opacity:.45;cursor:not-allowed}.import-row,.source-heading,.generation-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.import-row span,.generation-actions>span{font-size:10px;color:#525b65}.source-heading{justify-content:space-between;margin-top:12px}.inventory-hints,.source-item{border:1px solid #dce2e5;border-radius:6px;padding:10px 14px;margin:12px 0}.source-item small{color:#525b65;margin-left:10px}.source-item summary{padding:3px 0}.local-builder .hint{font-size:11px;margin-top:0}.generation-actions{margin-top:18px;border-top:1px solid #dce2e5;padding-top:16px}.generation-actions label{width:100px;margin:0}.generation-actions .generate{background:#e6f3ed;color:#525b65;font-weight:600;padding:12px 18px}.template-evidence{margin-top:16px;background:#ffffff;border-radius:6px;padding:12px 16px}.template-evidence h3{color:#191d21;margin:3px 0 8px}.template-evidence h3 span{color:#525b65;font-size:10px;margin-left:12px}.template-evidence ul{padding-left:16px;font-size:11px;color:#525b65;line-height:1.8;max-height:110px;overflow:auto}.source-links{display:flex;gap:12px;flex-wrap:wrap;font-size:11px;color:#525b65}.source-links a{color:#525b65;text-decoration:underline}.local-builder .ignored{color:#191d21;font-size:11px}.local-builder .local-error{color:#9a452b}@media(max-width:750px){.local-builder{padding:16px 12px}.local-heading{flex-wrap:wrap}.location-fields,.notes-grid{grid-template-columns:1fr}.generation-actions>span{width:100%}.binding{font-size:10px}.template-evidence h3 span{display:block;margin:7px 0}.source-links{overflow-wrap:anywhere}}
</style>
